def create(out_dir=None):
    write_batch(LESSONS, VISUALS, expected_count=12, out_dir=out_dir, label='Y8 English')


if __name__ == '__main__':
    import argparse
    from pathlib import Path
    p = argparse.ArgumentParser()
    p.add_argument('--out-dir', type=Path)
    args = p.parse_args()
    create(args.out_dir)
